import React from 'react';

import type {EntityIconProps} from '../EntityIcon';
import {EntityIcon} from '../EntityIcon';

import portfolioIcon from '../../../../assets/icons/portfolio.svg';

export type PortfolioIconProps = {portfolioId: string} & Omit<
    EntityIconProps,
    'data' | 'id' | 'alpha'
>;

export const PortfolioIcon = ({portfolioId, ...props}: PortfolioIconProps) => (
    <EntityIcon
        data={portfolioIcon}
        id={portfolioId}
        type="portfolio"
        alpha={0.5}
        withBackground={false}
        {...props}
    />
);

PortfolioIcon.displayName = 'PortfolioIcon';
